import { useState } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { inView, setActiveNotebook } from '@/db/repo.js';
import { patchSettings } from '@/db/mutations.js';
import { syncSoon } from '@/sync/store.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { LANGUAGE_NAMES } from '@/features/settings/data.js';
import { MergeSheet } from '@/features/settings/MergeSheet.js';
import { mergeChoices, type MergeChoice } from '@/features/settings/merge.js';
import { NewNotebookSheet } from './NewNotebookSheet.js';
import { NotebookEditSheet } from './NotebookEditSheet.js';
import styles from './NotebookSheet.module.css';

/**
 * The notebooks on this account, and the three things anybody does with
 * them: pick one, add one, put two together.
 *
 * It is one sheet opened from three places — Settings, Today and the
 * notebook itself — because a learner should not have to remember which
 * screen owns their notebooks. With a single notebook it is still worth
 * opening: the way to a second one is inside it.
 */
export function NotebookSheet({
  activeId,
  onClose,
}: {
  activeId: string | undefined;
  onClose: () => void;
}): React.JSX.Element {
  const notebooks = useLiveQuery(() => mergeChoices(), undefined, []);
  const view = useLiveQuery(() => inView(), undefined, []);
  const [adding, setAdding] = useState(false);
  const [merging, setMerging] = useState(false);
  const [editing, setEditing] = useState<string | undefined>();

  if (adding) {
    return (
      <NewNotebookSheet
        onCreated={onClose}
        onClose={() => {
          setAdding(false);
        }}
      />
    );
  }

  if (merging && activeId !== undefined) {
    return <MergeSheet activeId={activeId} onDone={onClose} onClose={onClose} />;
  }

  const list = notebooks ?? [];
  const across = view?.all === true;
  const chosen = list.find((notebook) => notebook.id === editing);

  /** One choice for the whole app: this notebook, or all of them. */
  const show = (all: boolean, notebookId?: string): void => {
    void patchSettings({ practiceScope: all ? 'all' : 'notebook' })
      .then(() => (notebookId === undefined ? undefined : setActiveNotebook(notebookId)))
      .then(() => {
        void syncSoon();
        onClose();
      });
  };

  if (chosen !== undefined) {
    return (
      <NotebookEditSheet
        notebook={chosen}
        canRemove={list.length > 1}
        onDone={onClose}
        onClose={() => {
          setEditing(undefined);
        }}
      />
    );
  }

  return (
    <Sheet title={t('notebooks.title')} onClose={onClose}>
      <div className={styles.body}>
        {list.length > 1 && <p className={styles.lead}>{t('notebooks.lead')}</p>}

        <div className={styles.group} role="radiogroup" aria-label={t('notebooks.title')}>
          {/* Everything at once, offered first and only where there is
              more than one notebook: with a single one the phrase would be
              true and useless. */}
          {list.length > 1 && (
            <AllRow
              words={list.reduce((sum, notebook) => sum + notebook.words, 0)}
              notebooks={list.length}
              chosen={across}
              onPick={() => {
                show(true);
              }}
            />
          )}
          {list.map((notebook) => (
            <Row
              key={notebook.id}
              notebook={notebook}
              chosen={!across && notebook.id === activeId}
              onPick={() => {
                if (!across && notebook.id === activeId) {
                  onClose();
                  return;
                }
                show(false, notebook.id);
              }}
              onEdit={() => {
                setEditing(notebook.id);
              }}
            />
          ))}
        </div>

        <button
          type="button"
          className={styles.add}
          onClick={() => {
            setAdding(true);
          }}
        >
          <Icon name="plus" size={17} weight={2.2} />
          {t('notebooks.new')}
        </button>

        {/* Two notebooks are not always what somebody wanted to end up
            with: a borrowed list becomes part of your own soon enough. */}
        {list.length > 1 && (
          <button
            type="button"
            className={styles.merge}
            onClick={() => {
              setMerging(true);
            }}
          >
            {t('merge.open')}
          </button>
        )}
      </div>
    </Sheet>
  );
}

/** Every notebook at once: one row, above the individual ones. */
function AllRow({
  words,
  notebooks,
  chosen,
  onPick,
}: {
  words: number;
  notebooks: number;
  chosen: boolean;
  onPick: () => void;
}): React.JSX.Element {
  return (
    <div className={cx(styles.row, chosen && styles.rowOn)}>
      <button type="button" role="radio" aria-checked={chosen} className={styles.pick} onClick={onPick}>
        <Mark chosen={chosen} />
        <span className={styles.text}>
          <span className={styles.name}>{t('notebooks.all')}</span>
          <span className={styles.sub}>{t('notebooks.allWords', { count: words, notebooks })}</span>
        </span>
      </button>
    </div>
  );
}

/**
 * One notebook: its name, its languages and how much is in it.
 *
 * Two targets in one row, because they are two different intentions: the row
 * itself switches to the notebook, and the pencil is for changing it. A
 * button inside a button is not valid markup, so the radio and the pencil
 * are siblings sharing a frame rather than one nested in the other.
 */
function Row({
  notebook,
  chosen,
  onPick,
  onEdit,
}: {
  notebook: MergeChoice;
  chosen: boolean;
  onPick: () => void;
  onEdit: () => void;
}): React.JSX.Element {
  return (
    <div className={cx(styles.row, chosen && styles.rowOn)}>
      <button type="button" role="radio" aria-checked={chosen} className={styles.pick} onClick={onPick}>
        <Mark chosen={chosen} />
        <span className={styles.text}>
          <span className={styles.nameRow}>
            <span className={styles.name} dir="auto">
              {notebook.title}
            </span>
            {/* A badge, not a third clause in the meta line: there it pushed
                the languages and the count onto a second row. */}
            {notebook.isDefault && <span className={styles.badge}>{t('notebooks.defaultTag')}</span>}
          </span>
          <span className={styles.sub}>
            {t('merge.pair', {
              target: LANGUAGE_NAMES[notebook.targetLang],
              meaning: LANGUAGE_NAMES[notebook.meaningLang],
            })}
            {' · '}
            {notebook.words === 0
              ? t('notebooks.empty')
              : notebook.words === 1
                ? t('notebooks.wordsOne')
                : t('notebooks.words', { count: notebook.words })}
          </span>
        </span>
      </button>
      <button
        type="button"
        className={styles.edit}
        aria-label={`${t('notebooks.edit')}: ${notebook.title}`}
        onClick={onEdit}
      >
        <Icon name="pencil" size={16} weight={2} />
      </button>
    </div>
  );
}

/**
 * Chosen or not, as a radio rather than a tick that appeared out of the
 * blue beside the pencil. Two icons at the same edge of a row, one of them
 * a state and the other an action, is a guess either way.
 */
function Mark({ chosen }: { chosen: boolean }): React.JSX.Element {
  return (
    <span className={cx(styles.mark, chosen && styles.markOn)} aria-hidden="true">
      {chosen && <Icon name="check" size={13} weight={2.8} />}
    </span>
  );
}
