import { useState } from 'react';
import { Button } from '@/components/ui/Button.js';
import { Confirm } from '@/components/ui/Confirm.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { removeNotebook, updateNotebook } from '@/db/mutations.js';
import { LANGUAGE_NAMES } from '@/features/settings/data.js';
import type { MergeChoice } from '@/features/settings/merge.js';
import { t } from '@/i18n/index.js';
import { syncSoon } from '@/sync/store.js';
import styles from './NotebookEditSheet.module.css';

/**
 * Renaming a notebook, and removing one.
 *
 * The two live together because they are the same thought — this notebook,
 * and what to do about it — and because separating them would mean two ways
 * into a list that has one row per notebook.
 *
 * Removing asks first and says the number out loud. A notebook is not a
 * label on some words: it is the words, their meanings, their examples and
 * every box they have climbed, and somebody who has not counted them
 * deserves to be told before they cannot be. Where the words are worth
 * keeping, merging is the better move, and the dialog says so rather than
 * letting somebody find out afterwards.
 */
export function NotebookEditSheet({
  notebook,
  canRemove,
  onDone,
  onClose,
}: {
  notebook: MergeChoice;
  /** False for the only notebook: the app has nowhere to stand without one. */
  canRemove: boolean;
  onDone: () => void;
  onClose: () => void;
}): React.JSX.Element {
  const [title, setTitle] = useState(notebook.title);
  const [said, setSaid] = useState('');
  const [busy, setBusy] = useState(false);
  const [removing, setRemoving] = useState(false);
  const [failed, setFailed] = useState('');

  const named = title.trim();
  const changed = named !== '' && named !== notebook.title;

  const save = (): void => {
    if (!changed) return;
    setBusy(true);
    setFailed('');
    void updateNotebook(notebook.id, { title: named })
      .then(() => syncSoon())
      .then(onDone)
      .catch(() => {
        setBusy(false);
        setFailed(t('notebooks.saveFailed'));
      });
  };

  /**
   * Handing the default over. It is written at once rather than on a save
   * button: it is one switch with one meaning, and nothing about it needs
   * confirming.
   */
  const makeDefault = (): void => {
    setBusy(true);
    setFailed('');
    void updateNotebook(notebook.id, { isDefault: true })
      .then(() => syncSoon())
      .then(() => {
        setBusy(false);
        setSaid(t('notebooks.defaultSet'));
      })
      .catch(() => {
        setBusy(false);
        setFailed(t('notebooks.saveFailed'));
      });
  };

  const remove = (): void => {
    setBusy(true);
    setFailed('');
    void removeNotebook(notebook.id)
      .then((gone) => {
        if (!gone) throw new Error('the last notebook stays');
        return syncSoon();
      })
      .then(onDone)
      .catch(() => {
        setBusy(false);
        setRemoving(false);
        setFailed(t('notebooks.removeFailed'));
      });
  };

  if (removing) {
    return (
      <Confirm
        title={t('notebooks.removeTitle', { title: notebook.title })}
        body={[
          notebook.words === 0
            ? t('notebooks.removeBodyEmpty')
            : notebook.words === 1
              ? t('notebooks.removeBodyOne')
              : t('notebooks.removeBody', { count: notebook.words }),
          ...(notebook.words > 0 ? [t('notebooks.removeKeep')] : []),
        ]}
        confirmLabel={t('notebooks.removeConfirm')}
        cancelLabel={t('notebooks.removeCancel')}
        danger
        busy={busy}
        onConfirm={remove}
        onCancel={() => {
          setRemoving(false);
        }}
      />
    );
  }

  return (
    <Sheet title={t('notebooks.editTitle')} onClose={onClose}>
      <div className={styles.body}>
        <label className={styles.field}>
          <span className={styles.label}>{t('notebooks.name')}</span>
          <input
            className={styles.input}
            value={title}
            dir="auto"
            maxLength={120}
            placeholder={t('notebooks.namePlaceholder', {
              target: LANGUAGE_NAMES[notebook.targetLang],
            })}
            autoFocus
            onChange={(event) => {
              setTitle(event.target.value);
              setFailed('');
            }}
            onKeyDown={(event) => {
              if (event.key === 'Enter') save();
            }}
          />
        </label>
        <p className={styles.pair}>
          {t('merge.pair', {
            target: LANGUAGE_NAMES[notebook.targetLang],
            meaning: LANGUAGE_NAMES[notebook.meaningLang],
          })}
        </p>

        <section className={styles.block}>
          <span className={styles.label}>{t('notebooks.default')}</span>
          {notebook.isDefault ? (
            <p className={styles.note}>{canRemove ? t('notebooks.defaultOn') : t('notebooks.defaultOnly')}</p>
          ) : (
            <Button variant="secondary" block disabled={busy} onClick={makeDefault}>
              {t('notebooks.makeDefault')}
            </Button>
          )}
          <p className={styles.note}>{t('notebooks.defaultWhy')}</p>
        </section>

        {said !== '' && (
          <p className={styles.said} role="status">
            {said}
          </p>
        )}
        {failed !== '' && <p className={styles.failed}>{failed}</p>}

        <Button block size="large" busy={busy} disabled={!changed} onClick={save}>
          {t('notebooks.save')}
        </Button>

        {canRemove ? (
          <Button
            variant="danger"
            block
            disabled={busy}
            onClick={() => {
              setRemoving(true);
            }}
          >
            {t('notebooks.remove')}
          </Button>
        ) : (
          <p className={styles.note}>{t('notebooks.removeLast')}</p>
        )}
      </div>
    </Sheet>
  );
}
