/**
 * Putting two notebooks into one.
 *
 * Copying a notebook somebody shared makes a second one, which is right —
 * their words are theirs and yours are yours, and the two may not even be
 * in the same languages. But once you have decided a borrowed list is part
 * of your own, carrying two notebooks around is the app getting in the way.
 * This is the way back to one.
 *
 * It is a move, not a copy: the words arrive in the other notebook with the
 * learning behind them intact, and the notebook they came from is removed.
 * A word already in the destination is left alone rather than duplicated,
 * because the one you have has your own boxes and notes on it.
 */
import { normalizeHeadword, type LanguageCode } from '@lexpad/core';
import { importWords, removeNotebook, type ImportRow } from '@/db/mutations.js';
import { countWords, listNotebooks, listWords } from '@/db/repo.js';

/** What a merge would do, worked out before anything is written. */
export interface MergePlan {
  /** Words that would move across. */
  moving: number;
  /** Words the destination already has, which stay as they are. */
  keeping: number;
  /**
   * Whether both notebooks are written in the same pair of languages. When
   * they are not, the words still move, but their meanings are in a
   * language the destination does not claim — which is the reader's call
   * to make, and so is said out loud rather than decided for them.
   */
  samePair: boolean;
}

export const NO_PLAN: MergePlan = { moving: 0, keeping: 0, samePair: true };

/** A notebook as the merge screen lists it. */
export interface MergeChoice {
  id: string;
  title: string;
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
  words: number;
  /** Where a word goes when every notebook is in view. Exactly one is. */
  isDefault: boolean;
}

/** Every notebook on this device, with what each one holds. */
export async function mergeChoices(): Promise<MergeChoice[]> {
  const notebooks = await listNotebooks();
  return Promise.all(
    notebooks.map(async (notebook) => ({
      id: notebook.id,
      title: notebook.title,
      targetLang: notebook.targetLang,
      meaningLang: notebook.meaningLang,
      words: await countWords(notebook.id),
      isDefault: notebook.isDefault,
    })),
  );
}

/** What merging `from` into `into` would do. Reads only. */
export async function planMerge(from: string, into: string): Promise<MergePlan> {
  if (from === into) return NO_PLAN;
  const notebooks = await listNotebooks();
  const source = notebooks.find((notebook) => notebook.id === from);
  const target = notebooks.find((notebook) => notebook.id === into);
  if (!source || !target) return NO_PLAN;

  const [moving, existing] = await Promise.all([listWords(from), listWords(into)]);
  const have = new Set(existing.map((word) => normalizeHeadword(word.headword)));
  let keeping = 0;
  for (const word of moving) {
    if (have.has(normalizeHeadword(word.headword))) keeping += 1;
  }
  return {
    moving: moving.length - keeping,
    keeping,
    samePair: source.targetLang === target.targetLang && source.meaningLang === target.meaningLang,
  };
}

/**
 * Moves every word across and removes the emptied notebook.
 *
 * The words keep the day they were added and their place in the order, so
 * the merged notebook still reads as a diary rather than a pile, and they
 * keep their boxes: merging must never cost somebody a month of practice.
 * Relations between words that move together survive, remapped to the ids
 * they are given on arrival.
 */
export async function mergeNotebooks(from: string, into: string, timeZone: string): Promise<MergePlan> {
  const plan = await planMerge(from, into);
  if (from === into) return plan;

  const existing = await listWords(into);
  const have = new Set(existing.map((word) => normalizeHeadword(word.headword)));
  const rows: ImportRow[] = [];
  for (const word of await listWords(from)) {
    if (have.has(normalizeHeadword(word.headword))) continue;
    const {
      id,
      notebookId: _notebookId,
      position,
      createdAt,
      updatedAt: _updatedAt,
      progress,
      ...card
    } = word;
    rows.push({
      ref: id,
      word: card,
      // Ids of the old notebook; the import remaps the ones that move too.
      relatedRefs: word.relatedWordIds ?? [],
      ...(progress === undefined ? {} : { progress }),
      createdAt,
      position,
    });
  }

  if (rows.length > 0) await importWords(into, rows, timeZone);
  await removeNotebook(from);
  return plan;
}
