import { useState } from 'react';
import { Button } from '@/components/ui/Button.js';
import { Confirm } from '@/components/ui/Confirm.js';
import { Icon } from '@/components/ui/Icon.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { localTimeZone } from '@/lib/format.js';
import { setActiveNotebook } from '@/db/repo.js';
import { syncSoon } from '@/sync/store.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { LANGUAGE_NAMES } from './data.js';
import { mergeChoices, mergeNotebooks, planMerge, NO_PLAN, type MergeChoice } from './merge.js';
import styles from './MergeSheet.module.css';

/**
 * Putting two notebooks into one.
 *
 * The screen answers the two questions a merge has — which words move, and
 * where they land — in that order, and then says exactly what will happen
 * before anything does. Almost always there are two notebooks and one
 * answer to the second question, so the destination picks itself and the
 * reader only chooses a direction.
 *
 * Nothing is counted in the abstract: the line above the button is the real
 * number of words that will move, read from the notebooks themselves.
 */
export function MergeSheet({
  activeId,
  onDone,
  onClose,
}: {
  /** The notebook the app is showing, which is the natural destination. */
  activeId: string;
  onDone: () => void;
  onClose: () => void;
}): React.JSX.Element {
  const choices = useLiveQuery(() => mergeChoices(), undefined, []);
  // What the reader has tapped, if anything. The defaults are worked out
  // from the list rather than stored, so they follow it when it changes.
  const [pickedFrom, setPickedFrom] = useState<string | undefined>();
  const [pickedInto, setPickedInto] = useState<string | undefined>();
  const [asking, setAsking] = useState(false);
  const [busy, setBusy] = useState(false);
  const [failed, setFailed] = useState(false);

  const list = choices ?? [];
  // The notebook that is not being shown is the one somebody is most
  // likely to be folding away, so it leads.
  const from = pickedFrom ?? list.find((choice) => choice.id !== activeId)?.id ?? list[0]?.id;
  const rest = list.filter((choice) => choice.id !== from);
  // The destination is whatever is left. With two notebooks there is one
  // answer, so it is chosen rather than asked for.
  const into =
    (pickedInto !== from ? pickedInto : undefined) ??
    rest.find((choice) => choice.id === activeId)?.id ??
    rest[0]?.id;

  const plan = useLiveQuery(
    async () => (from === undefined || into === undefined ? NO_PLAN : planMerge(from, into)),
    NO_PLAN,
    [from, into],
  );

  const source = list.find((choice) => choice.id === from);
  const target = list.find((choice) => choice.id === into);

  if (asking && source && target) {
    return (
      <Confirm
        title={t('merge.confirmTitle')}
        body={t('merge.confirmBody', { into: target.title, from: source.title })}
        confirmLabel={t('merge.confirm')}
        busy={busy}
        onCancel={() => {
          setAsking(false);
        }}
        onConfirm={() => {
          setBusy(true);
          setFailed(false);
          void mergeNotebooks(source.id, target.id, localTimeZone())
            .then(() => setActiveNotebook(target.id))
            .then(() => syncSoon())
            .then(onDone)
            .catch(() => {
              setBusy(false);
              setAsking(false);
              setFailed(true);
            });
        }}
      />
    );
  }

  return (
    <Sheet title={t('merge.title')} onClose={onClose}>
      <div className={styles.body}>
        <p className={styles.lead}>{t('merge.lead')}</p>

        <p className={styles.legend} id="merge-from">
          {t('merge.from')}
        </p>
        <div className={styles.group} role="radiogroup" aria-labelledby="merge-from">
          {list.map((choice) => (
            <Row
              key={choice.id}
              choice={choice}
              active={choice.id === activeId}
              chosen={choice.id === from}
              onPick={() => {
                setPickedFrom(choice.id);
                setPickedInto(undefined);
              }}
            />
          ))}
        </div>

        <p className={styles.legend} id="merge-into">
          {t('merge.into')}
        </p>
        <div className={styles.group} role="radiogroup" aria-labelledby="merge-into">
          {rest.map((choice) => (
            <Row
              key={choice.id}
              choice={choice}
              active={choice.id === activeId}
              chosen={choice.id === into}
              onPick={() => {
                setPickedInto(choice.id);
              }}
            />
          ))}
        </div>

        {source !== undefined && target !== undefined && (
          <p className={styles.summary} role="status">
            {plan.moving === 0
              ? t('merge.nothing')
              : `${plan.moving === 1 ? t('merge.summaryOne') : t('merge.summary', { count: plan.moving })}${
                  plan.keeping === 0
                    ? ''
                    : ` ${plan.keeping === 1 ? t('merge.keepingOne') : t('merge.keeping', { count: plan.keeping })}`
                }`}
          </p>
        )}

        {/* The words move either way; saying so is the reader's call to
            make, not ours to take away from them. */}
        {source !== undefined && target !== undefined && !plan.samePair && (
          <p className={styles.warn}>
            <Icon name="note" size={15} weight={1.9} />
            <span>
              {t('merge.differentLanguages', {
                meaning: LANGUAGE_NAMES[source.meaningLang],
                into: LANGUAGE_NAMES[target.meaningLang],
              })}
            </span>
          </p>
        )}

        {failed && <p className={styles.error}>{t('merge.failed')}</p>}

        <Button
          block
          size="large"
          disabled={source === undefined || target === undefined}
          onClick={() => {
            setAsking(true);
          }}
        >
          {plan.moving === 1
            ? t('merge.actionOne')
            : plan.moving === 0
              ? t('merge.actionNone')
              : t('merge.action', { count: plan.moving })}
        </Button>
      </div>
    </Sheet>
  );
}

/**
 * One notebook to choose.
 *
 * Two copies of the same list have the same name, the same languages and
 * often the same number of words — which is exactly the case this screen
 * exists for. Which one the app is showing is the one thing that always
 * tells them apart, so it is on the row.
 */
function Row({
  choice,
  active,
  chosen,
  onPick,
}: {
  choice: MergeChoice;
  active: boolean;
  chosen: boolean;
  onPick: () => void;
}): React.JSX.Element {
  return (
    <button
      type="button"
      role="radio"
      aria-checked={chosen}
      className={cx(styles.row, chosen && styles.rowOn)}
      onClick={onPick}
    >
      <span className={styles.text}>
        <span className={styles.titleRow}>
          <span className={styles.title} dir="auto">
            {choice.title}
          </span>
          {active && <span className={styles.badge}>{t('merge.showing')}</span>}
        </span>
        <span className={styles.sub}>
          {t('merge.pair', {
            target: LANGUAGE_NAMES[choice.targetLang],
            meaning: LANGUAGE_NAMES[choice.meaningLang],
          })}
          {' · '}
          {choice.words === 0
            ? t('merge.empty')
            : choice.words === 1
              ? t('merge.wordsOne')
              : t('merge.words', { count: choice.words })}
        </span>
      </span>
      {chosen && <Icon name="check" size={16} weight={2.4} />}
    </button>
  );
}
